using System;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 public sealed class IndustrySaveTests {
  static string Hash(string s){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(s))).Replace("-","").ToLowerInvariant();}
  [Test]public void VersionFourPreservesAllExistingFieldsAndItsOriginalBytes(){string dir=Path.Combine(Path.GetTempPath(),"unity-industry-v4-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var codec=new UnitySaveCodec();var s=Game.Buy(Game.New(1000),"calculator");s=Workshop.Discover(s);s.Credits=ScientificNumber.From(100000);s.Data=ScientificNumber.From(100000);s=Game.Train(s,"quality");s=Game.Research(s,"dataGeneration");s.Meta.models[9]=15;s.Workshop.activeModel="K10";s.Workshop.activeModelLevel=15;s.Workshop.inventory=new[]{new ItemInstance{id="existing",type="quantum-chip",level=12,forge=3,rarity=4}};s=Workshop.Equip(s,"existing","universal2");var dto=StateData.From(s);dto.industry=null;dto.research=dto.research.Take(10).ToArray();string payload=codec.Encode(dto),raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=4,payload=payload,sha256=Hash(payload)}),path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,codec);var load=store.Load(1000);Assert.That(load.Writable,Is.True,load.Message);var expected=StateData.From(s);expected.industry=load.State.Industry.Copy();Assert.That(JsonUtility.ToJson(StateData.From(load.State)),Is.EqualTo(JsonUtility.ToJson(expected)));Assert.That(load.State.Research.Length,Is.EqualTo(26));Assert.That(load.State.Research.Skip(10),Is.All.Zero);Assert.That(load.State.Industry.trainingStarted,Is.Zero,"Same default as source researchMigration; no guessed history");Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v4-original-*").Single()),Is.EqualTo(raw));store.Save(load.State);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(5));Assert.That(File.ReadAllText(path+".backup"),Is.EqualTo(raw));}finally{Directory.Delete(dir,true);}}
  [Test]public void MissingIndustryOrMalformedPaidContractsAreRejected(){var dto=StateData.From(Game.New(1000));dto.industry=null;Assert.Throws<FormatException>(()=>dto.ToState());var s=Game.New(1000);s.Industry.synthesis=new Job{id="circuits",required=double.NaN};Assert.Throws<FormatException>(()=>Game.Validate(s));s=Game.New(1000);s.Industry.foundries=new[]{new FoundryState{level=6}};Assert.Throws<FormatException>(()=>Game.Validate(s));}
 }
}
